mapper.select:
SELECT m.merchant_id, m.name, mc.merchant_category_id, mc.category_code, mc.category_name FROM merchants m INNER JOIN merchant_categories mc ON mc.merchant_category_id = m.merchant_category_id WHERE m.status = 'active' AND m.merchant_id IN
#{merchantId}
ORDER BY m.merchant_id

SELECT category.merchant_category_id
FROM merchant_categories category
WHERE category.merchant_category_id = #{merchantCategoryId}

SELECT merchant.merchant_id, merchant.merchant_category_id FROM merchants merchant WHERE merchant.merchant_id IN
#{merchantId}
ORDER BY merchant.merchant_id, merchant.merchant_category_id

SELECT merchant.merchant_id, merchant.name AS merchant_name, mc.category_code, mc.category_name, uc.user_card_id, COALESCE(cv.name, uc.card_name_from_codef) AS card_name, i.issuer_name, NULLIF(cv.image_url, '') AS card_image_url, o.offer_id, o.offer_name, o.reward_type, r.position AS benefit_tier_position, r.reward_unit, r.reward_value, r.reward_basis_amount, r.transaction_min_krw, r.previous_spend_min_krw, COALESCE(ps.current_spend_amount, 0) AS previous_month_spend_krw, COALESCE(o.reference_value_krw, conversion.krw_per_unit, 1) AS krw_per_reward_unit, (SELECT MAX(tier.limit_value) FROM benefit_limit_policies policy INNER JOIN benefit_limit_tiers tier ON tier.limit_policy_id = policy.limit_policy_id WHERE policy.offer_id = o.offer_id AND policy.limit_period = 'monthly' AND policy.limit_type = 'reward_amount' AND policy.limit_unit = 'KRW' AND (tier.previous_spend_min_krw IS NULL OR tier.previous_spend_min_krw <= COALESCE(ps.current_spend_amount, 0))) AS monthly_limit_krw, COALESCE((SELECT SUM(benefit_usage.reward_amount_krw) FROM user_benefit_usages benefit_usage WHERE benefit_usage.user_card_id = uc.user_card_id AND (benefit_usage.offer_id = o.offer_id OR benefit_usage.limit_policy_id IN ( SELECT sibling.limit_policy_id FROM benefit_limit_policies current_policy INNER JOIN benefit_limit_policies sibling ON sibling.shared_group_key = current_policy.shared_group_key WHERE current_policy.offer_id = o.offer_id AND current_policy.shared_group_key IS NOT NULL)) AND benefit_usage.usage_status = 'confirmed' AND benefit_usage.usage_date >= DATE_FORMAT(#{usageDate}, '%Y-%m-01') AND benefit_usage.usage_date < DATE_ADD(DATE_FORMAT(#{usageDate}, '%Y-%m-01'), INTERVAL 1 MONTH)), 0) AS monthly_used_krw, r.rule_id, r.rule_effect, r.valid_from, r.valid_to, t.match_mode, t.target_type, t.merchant_category_id AS target_merchant_category_id, t.merchant_id AS target_merchant_id, t.minimum_place_confidence, EXISTS (SELECT 1 FROM benefit_rule_schedules schedule WHERE schedule.rule_id = r.rule_id) AS has_schedule, EXISTS (SELECT 1 FROM benefit_offer_option_requirements requirement WHERE requirement.offer_id = o.offer_id) AS has_option_requirement FROM merchants merchant INNER JOIN merchant_categories mc ON mc.merchant_category_id = merchant.merchant_category_id INNER JOIN user_cards uc ON uc.user_id = #{userId} AND uc.is_active = TRUE INNER JOIN issuers i ON i.issuer_id = uc.issuer_id INNER JOIN card_content_versions cv ON cv.card_id = uc.card_id AND NOT EXISTS (SELECT 1 FROM card_content_versions newer WHERE newer.card_id = cv.card_id AND (newer.last_seen_at > cv.last_seen_at OR (newer.last_seen_at = cv.last_seen_at AND newer.content_version_id > cv.content_version_id))) INNER JOIN card_benefits cb ON cb.content_version_id = cv.content_version_id INNER JOIN benefit_offers o ON o.benefit_id = cb.benefit_id INNER JOIN benefit_rules r ON r.offer_id = o.offer_id INNER JOIN benefit_rule_targets t ON t.rule_id = r.rule_id LEFT JOIN user_card_performance_snapshots ps ON ps.user_card_id = uc.user_card_id AND ps.performance_month = #{performanceMonth} LEFT JOIN reward_conversion_policies conversion ON conversion.reward_program_id = o.reward_program_id AND conversion.valid_from <= #{usageDate} AND (conversion.valid_to IS NULL OR conversion.valid_to >= #{usageDate}) WHERE merchant.status = 'active' AND merchant.merchant_id IN
#{merchantId}
ORDER BY merchant.merchant_id, uc.display_order, uc.user_card_id, r.priority DESC, r.rule_id, t.condition_group, t.match_mode, t.target_id
